import React from "react";
import { Link, useLocation } from "react-router-dom";
import Swal from "sweetalert2";
import withReactContent from "sweetalert2-react-content";
import axios from "axios";
import "../styles/main.css";

const MySwal = withReactContent(Swal);

export default function Header() {
  const location = useLocation();

  const navItems = [
    { name: "Home", path: "/" },
    { name: "The School", path: "/school" },
    { name: "Admissions", path: "/admissions" },
    { name: "Fee Structure", path: "/fees" },
    { name: "Academics", path: "/academics" },
    { name: "Extra Curricular", path: "/extracurricular" },
    { name: "Download", path: "/download" },
    { name: "Gallery", path: "/gallery" },
    { name: "Mandatory Disclosure", path: "/mandatory-disclosure" },
    { name: "Contact", path: "/contact" },
  ];

  // Helper function to decide visible fees based on class
  const getVisibleFeeKeys = (cls) => {
    if (cls <= 5) return ["tuition", "development", "transport"];
    if (cls >= 6 && cls <= 9)
      return ["tuition", "development", "computer", "transport", "sports"];
    return [
      "tuition",
      "development",
      "computer",
      "transport",
      "sports",
      "artMusic",
    ];
  };

  // 🧾 Pay Fee Popup
  const handlePayFeeClick = async () => {
    const { value: admissionNumber } = await MySwal.fire({
      title: "💳 Pay School Fees",
      input: "text",
      inputPlaceholder: "Enter Admission Number (e.g. KV-000001)",
      showCancelButton: true,
      confirmButtonText: "Search",
      inputValidator: (value) => {
        if (!value) return "Please enter admission number";
      },
    });

    if (!admissionNumber) return;

    try {
      const res = await axios.get(`http://localhost:5000/api/fees/${admissionNumber}`);
      const summary = res.data;

      if (!summary || !summary.student) {
        MySwal.fire("Not Found", "No record found for that admission number", "error");
        return;
      }

      const mainFeeKeys = getVisibleFeeKeys(Number(summary.student.className));

      const feeList = mainFeeKeys.map((key) => {
        const nameMap = {
          tuition: "Tuition Fee",
          development: "Development / Infrastructure Fee",
          computer: "Computer / Lab Fee",
          transport: "Transport / Bus Fee",
          sports: "Sports / Gym / PT Fee",
          artMusic: "Art / Music / Dance Fee",
        };
        return `<tr><td>${nameMap[key]}</td><td>₹${summary.fees[key] || 0}</td></tr>`;
      });

      const totalAmount = mainFeeKeys.reduce(
        (sum, key) => sum + (summary.fees[key] || 0),
        0
      );

      // 🧾 Show Fee Details Popup
      MySwal.fire({
        title: `💳 ${summary.student.name} — Class ${summary.student.className}`,
        html: `
          <table style="width:100%; text-align:left; margin-top:10px; border-collapse: collapse;">
            <tr><th>Particulars</th><th>Amount (₹)</th></tr>
            ${feeList.join("")}
            <tr style="border-top:1px solid #ccc;">
              <td><strong>Total</strong></td>
              <td><strong>₹${totalAmount}</strong></td>
            </tr>
          </table>
          <div style="margin-top:15px;">
            <input type="number" id="payAmount" class="swal2-input" placeholder="Enter amount to pay" />
          </div>
        `,
        confirmButtonText: "Pay Now",
        showCancelButton: true,
        preConfirm: () => {
          const payAmount = document.getElementById("payAmount").value;
          if (!payAmount || payAmount <= 0)
            MySwal.showValidationMessage("Enter a valid payment amount");
          return payAmount;
        },
      }).then((result) => {
        if (result.isConfirmed) {
          const paid = Number(result.value);
          const remaining = totalAmount - paid;

          MySwal.fire({
            icon: "success",
            title: "✅ Payment Successful!",
            html: `
              <p><strong>Paid:</strong> ₹${paid}</p>
              <p><strong>Remaining:</strong> ₹${remaining < 0 ? 0 : remaining}</p>
            `,
            confirmButtonText: "OK",
          });
        }
      });
    } catch (err) {
      console.error(err);
      MySwal.fire("Error", "Something went wrong while fetching fee details.", "error");
    }
  };

  return (
    <header className="site-header">
      <div className="topbar">
        <div className="top-left">
          <img src="/assets/logo.png" alt="logo" className="logo" />
          <div className="school-meta">
            <div className="school-name">Kendriya Vidyalaya Sector-24 Noida</div>
            <div className="school-sub">
              CBSE Board Affiliated Co-Ed English Medium Senior Secondary School
            </div>
          </div>
        </div>

        <div className="top-right">
          <button className="payfee-btn" onClick={handlePayFeeClick}>
            💳 Pay Fee
          </button>
          <Link to="/admin/login" className="login-btn">
            Admin Login
          </Link>
        </div>
      </div>

      <nav className="main-nav">
        <div className="nav-inner">
          {navItems.map((item) => {
            const active =
              location.pathname === item.path ||
              (location.pathname === "/" && item.path === "/");
            return (
              <Link
                key={item.name}
                to={item.path}
                className={`nav-item ${active ? "active" : ""}`}
              >
                {item.name}
              </Link>
            );
          })}
        </div>
      </nav>
    </header>
  );
}
